async function api(body,query=''){const controller=typeof AbortController!=='undefined'?new AbortController():null,timer=controller?setTimeout(()=>controller.abort(),45000):null;try{const r=await fetch('/api/delta-desk/learning'+query,{cache:'no-store',method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:controller?.signal});let d;try{d=await r.json()}catch{throw Error('History service returned an unreadable response ('+r.status+'). Retry after checking your connection.')}if(!d||typeof d!=='object'||Array.isArray(d))throw Error('History service returned an invalid response. Retry; saved progress is retained.');if(!r.ok||d.error)throw Error(d.error||'History request failed');return d}catch(e){if(e.name==='AbortError')throw Error('History request timed out. Your saved progress is safe. Please retry.');throw e}finally{if(timer)clearTimeout(timer)}}
function controls(){const busy=running||loading;for(const id of ['learningSync','learningStart','learningEnd','learningApply','learningRecalculate'])$(id).disabled=busy;main.querySelectorAll('[data-period]').forEach(b=>b.disabled=busy);$('learningPause').hidden=!running;$('learningResume').hidden=busy||!job||job.stage>=3;const same=job&&day(job.start)===$('learningStart').value&&day(job.end-1)===$('learningEnd').value;$('learningSync').textContent=busy?'Loading…':retryLatest?'Retry loading':same&&job.stage<3?'Continue loading':!report||$('learningStart').value<day(job.start)||$('learningEnd').value>day(job.end-1)?'Load this period':'Refresh results';$('learningResume').hidden=true;}
